<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {Award,ArrowRight,RefreshCw,Check,ShieldCheck} from 'lucide-vue-next'
import {api,cash,date,type Row} from '../lib'
import DataTable from './DataTable.vue'
const data=ref<Row>({}),error=ref(''),loading=ref(false)
async function load(){loading.value=true;try{data.value=await api('/membership');error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{load();timer=setInterval(()=>{if(document.visibilityState==='visible'&&!loading.value)load()},15000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="membership-page" :aria-busy="loading"><div class="page-heading"><div><span class="eyebrow">GROW WITH EVERY ORDER</span><h1>会员中心</h1><p>每一笔成功办理，积累下一程的专属优惠。</p></div><button class="btn secondary" @click="load" :disabled="loading"><RefreshCw :size="16"/>刷新等级</button></div><div v-if="error" class="alert danger">{{error}}</div>
<template v-if="data.membership"><section class="membership-hero"><div class="membership-emblem"><Award :size="44"/><b>{{data.membership.current.code}}</b></div><div class="membership-intro"><span class="eyebrow">你的当前等级</span><h2>{{data.membership.current.name}}</h2><p>服务费{{data.membership.current.discount===100?'按标准价':'减免 '+(100-data.membership.current.discount)+'%'}}</p><span class="pill">{{data.membership.source==='manual'?'运营指定等级':'消费自动定级'}}</span><small v-if="data.membership.source==='manual'">{{data.membership.until?'有效至 '+date(data.membership.until):'长期有效'}} · 到期恢复自动等级</small></div><div class="membership-growth"><div class="growth-heading"><span>累计有效消费</span><b>{{cash(data.membership.spent)}} R</b></div><div class="growth-track" role="progressbar" aria-label="会员升级进度" :aria-valuenow="data.membership.progress" aria-valuemin="0" aria-valuemax="100"><i :style="{width:data.membership.progress+'%'}"></i></div><p v-if="data.membership.next">再消费 <b>{{cash(data.membership.remaining)}} R</b>，自动等级升至 {{data.membership.next.name}}</p><p v-else>已达到最高自动等级</p><small v-if="data.membership.source==='manual'">自动等级：{{data.membership.automatic.name}}；成长进度独立累计。</small><a href="#/subscribe" class="btn mint">查看订阅方案<ArrowRight :size="16"/></a></div></section>
<div v-if="data.membership.fee_override!=null" class="callout">你的账户已设置专属服务单价 {{cash(data.membership.fee_override)}} R / 次，优先于会员折扣。成长仍按订单实际结算的服务费累计。</div>
<div class="section-heading"><h2>每一阶，都看得见</h2><span class="muted">{{data.membership.tiers.length}} 档权益 · 自动更新</span></div><div class="membership-tiers"><article v-for="t in data.membership.tiers" :key="t.code" class="panel membership-tier" :class="{current:t.code===data.membership.current.code}"><div><span class="tier-code">{{t.code}}</span><span v-if="t.code===data.membership.current.code" class="pill"><Check :size="13"/>当前等级</span><span v-else-if="data.membership.spent>=t.threshold" class="muted small">已达门槛</span></div><h3>{{t.name}}</h3><strong>{{100-t.discount}}<small>% 服务费减免</small></strong><p>累计有效消费 {{cash(t.threshold)}} R</p><small>{{t.description||'达到门槛后自动享受对应服务费优惠'}}</small></article></div>
<div class="section-heading"><h2>我的套餐报价</h2><span class="muted small">金额单位：R · 按创建订单时的规则锁定</span></div><div class="panel"><DataTable :searchable="false" :rows="data.products" :columns="[{key:'name',label:'服务方案'},{key:'fee',label:'标准服务费'},{key:'benefit',label:'计价方式'},{key:'member_fee',label:'我的服务费'},{key:'enabled',label:'状态'}]"><template #fee="{row}">{{cash(row.fee)}} R</template><template #benefit>{{data.membership.fee_override!=null?'账户专属单价':'会员减免 '+(100-data.membership.current.discount)+'%'}}</template><template #member_fee="{row}"><b class="positive">{{cash(row.member_fee)}} R</b><small v-if="row.saved>0">节省 {{cash(row.saved)}} R</small></template><template #enabled="{row}"><span class="badge" :class="row.enabled?'active':'disabled'">{{row.enabled?'开放':'暂停'}}</span></template></DataTable></div>
<div class="membership-rules"><article class="panel"><ShieldCheck :size="22"/><h3>按成功结算累计</h3><p>成功订单已扣除的服务费计入成长，充值、兑换、调账、草稿和失败订单不计入。服务费退回会扣除相应成长，最低为零。</p></article><article class="panel"><Check :size="22"/><h3>报价和记录一致</h3><p>网页与 API 使用同一套等级报价。会员折扣用于平台服务费；上游订阅费用独立结算。历史订单保留当时等级和价格。</p></article><article class="panel"><Award :size="22"/><h3>规则透明可查</h3><p>等级门槛和折扣以本页当前规则为准。运营指定等级到期后自动恢复消费等级，专属单价优先于等级优惠。</p></article></div>
<div class="section-heading"><h2>成长明细</h2><span class="muted small">最近 100 笔成功订单，展示扣除服务退费后的有效消费</span></div><div class="panel"><DataTable :rows="data.growth" :columns="[{key:'id',label:'订单编号'},{key:'product_name',label:'服务方案'},{key:'spent',label:'有效消费'},{key:'updated_at',label:'订单更新时间'}]"><template #spent="{row}">{{cash(row.spent)}} R</template><template #updated_at="{row}">{{date(row.updated_at)}}</template></DataTable></div>
</template></div></template>
